def check_occurences(tuples_list):
    from collections import defaultdict
    occurrence_dict = defaultdict(int)

    for a, b in tuples_list:
        sorted_tuple = tuple(sorted((a, b)))  # Sort the tuple to ensure uniqueness
        occurrence_dict[sorted_tuple] += 1

    return dict(occurrence_dict)
