import math
from functools import lru_cache

def count_binary_seq(n):
    @lru_cache(None)
    def count_sequences(n, balance):
        # Base case: if no bits left and balance is zero, it's a valid sequence
        if n == 0:
            return 1 if balance == 0 else 0

        # Recursive case: add either a 0 or 1 to each half of the sequence
        # Adjust balance accordingly
        return count_sequences(n - 1, balance + 1) + count_sequences(n - 1, balance - 1)

    # Start with a balance of 0 and calculate valid sequences for one half
    return float(count_sequences(n, 0))

# Example usage with test cases
