def find_sum(lst):
    # Create a dictionary to count occurrences of each element
    element_count = {}
    for num in lst:
        if num in element_count:
            element_count[num] += 1
        else:
            element_count[num] = 1

    # Sum elements that appear only once
    return sum(num for num, count in element_count.items() if count == 1)

# Example usage and test
assert find_sum([1, 2, 3, 1, 1, 4, 5, 6]) == 21
assert find_sum([7, 8, 8, 9, 10, 7]) == 19
assert find_sum([1, 1, 1, 1, 2]) == 2
assert find_sum([]) == 0
```

