def merge_dictionaries_three(dict1, dict2, dict3):
    # Create an empty dictionary to store the merged result.
    merged_dict = {}

    # Iterate through the dictionaries in the order provided.
    for d in [dict1, dict2, dict3]:
        # Update the merged dictionary with the current dictionary.
        # If a key already exists, the value from the later dictionary overrides the previous one.
        merged_dict.update(d)

    return merged_dict

# Example usage:
